import{_ as o,c as t,o as i,ah as n}from"./chunks/framework.D6otvB2a.js";const r="/assets/vscode-open-recent-dropdown.BLZc4U5S.png",s="/assets/vscode-open-folder-prompt-workspace.B-PzKkkH.png",a="/assets/vscode-open-workspace-popup.DEL7OCd-.png",c="/assets/vscode-recommended-extensions-popup.B6qrNv9H.png",d="/assets/vscode-command-palette.Cb2A4l5t.png",p="/assets/vscode-recommended-extensions-sidebar.DCbrLXMD.png",k=JSON.parse('{"title":"Per-Project Setup","description":"","frontmatter":{},"headers":[],"relativePath":"per-project-setup.md","filePath":"per-project-setup.md","lastUpdated":1787780480000}'),l={name:"per-project-setup.md"};function h(u,e,g,m,y,f){return i(),t("div",null,e[0]||(e[0]=[n('<h1 id="per-project-setup" tabindex="-1">Per-Project Setup <a class="header-anchor" href="#per-project-setup" aria-label="Permalink to &quot;Per-Project Setup&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This page contains instructions for creating your own personal repository for a project in this course, cloning it, and getting it set up inside your dev container. You will need to complete these steps <strong>once per project</strong> in this course, after completing the <a href="/student-environment">Student Environment</a> setup.</p></div><h2 id="setup-instructions" tabindex="-1">Setup Instructions <a class="header-anchor" href="#setup-instructions" aria-label="Permalink to &quot;Setup Instructions&quot;">​</a></h2><h3 id="create-a-repository-from-the-template" tabindex="-1">Create a Repository From the Template <a class="header-anchor" href="#create-a-repository-from-the-template" aria-label="Permalink to &quot;Create a Repository From the Template&quot;">​</a></h3><p>A template repository is a special kind of GitHub repository that lets you generate a brand new repository with the same starter files, folder structure, and history-free commit as the template, but under your own account. For each project in this course, course staff provide a template repository (e.g.: <code>project-1-starter</code>) containing the starter code, instructions, and configuration you&#39;ll need. Using the template feature ensures you get your own independent, private copy to work in, rather than modifying the shared template directly.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Make sure you are signed in to <a href="https://github.com/" target="_blank" rel="noreferrer">GitHub</a> with your own personal account before starting these steps.</p></div><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>When you get to the <code>Visibility</code> setting below, do <strong>not</strong> select <code>Public</code>! Making your repository public exposes your work to other students (and the internet), which is an academic integrity violation. If you accidentally create a public repository, see the <a href="#common-issues">Common Issues</a> section below to fix it immediately.</p></div><ol><li>Navigate to the starter template repository for the project you are starting (e.g.: <code>https://github.com/CSCI-442-Mines/PROJECT_NAME-starter</code>, where <code>PROJECT_NAME</code> is the name of the project, such as <code>project-1</code>).</li><li>Click the green <code>Use this template</code> button near the top right of the page, then select <code>Create a new repository</code> from the dropdown menu.</li><li>On the <code>Create a new repository</code> page, fill out the following fields: <ul><li><strong>Owner</strong>: select your own personal GitHub account (<strong>not</strong> the <code>CSCI-442-Mines</code> organization). You will not have permission to create repositories directly under the organization.</li><li><strong>Repository name</strong>: name your repository <code>PROJECT_NAME-USERNAME</code>, where <code>PROJECT_NAME</code> is the name of the project (e.g.: <code>project-1</code>) and <code>USERNAME</code> is your GitHub username (e.g.: <code>ghost</code>). For example: <code>project-1-ghost</code>.</li><li><strong>Visibility</strong>: select <code>Private</code>.</li></ul></li><li>Leave the remaining options (such as <code>Include all branches</code>) at their default (unchecked) values.</li><li>Click the green <code>Create repository</code> button and wait for GitHub to finish generating your new repository from the template.</li></ol><h3 id="find-your-repository-url" tabindex="-1">Find Your Repository URL <a class="header-anchor" href="#find-your-repository-url" aria-label="Permalink to &quot;Find Your Repository URL&quot;">​</a></h3><p>Once your repository has been created, you&#39;ll land on its main page. Click the green <code>Code</code> button, and copy either the HTTPS or SSH URL, depending on which authentication method you set up in the <a href="/dev-container-setup#setup-git-inside-the-dev-container">Setup Git Inside the Dev Container</a> section.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep this URL handy! You&#39;ll use it as <code>PROJECT_REPOSITORY_URL</code> when cloning your repository below.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Failure to follow the remaining instructions on this page <strong>exactly</strong> as presented may result in corrupting your source code!</p></div><h3 id="clone-your-repository" tabindex="-1">Clone Your Repository <a class="header-anchor" href="#clone-your-repository" aria-label="Permalink to &quot;Clone Your Repository&quot;">​</a></h3><p>Now that you&#39;ve created your repository from the template above, you need to clone it. This will create a copy of the starter code and instructions on your local machine. For best results clone the repository from inside the dev container using <strong>one</strong> of the following methods:</p><ol><li>(Recommended) Open VS Code, select <code>File &gt; Open Recent</code>: <img src="'+r+'" alt="Open recent dropdown" data-zoomable="true"> and then select the <code>PATH_TO_DIRECTORY/student-env [Dev Container]</code> (Where <code>PATH_TO_DIRECTORY</code> is the actual path to the directory). Note that you <strong>must select the <code>[Dev Container]</code> entry</strong>!</li><li>Open VS Code, select <code>File &gt; Open Folder...</code>, navigate to the directory where you extracted the course dev container, and click on <code>Reopen in Container</code> popup (the same way you did for <a href="/dev-container-setup">setting up the course dev container</a>).</li></ol><p>Now that you&#39;ve opened the dev container, open the top level of the workspace directory in the dev container by selecting <code>File &gt; Open Folder...</code>, navigate to the <code>/workspace/</code> directory, and click <code>Ok</code>:</p><p><img src="'+s+'" alt="Open folder prompt for the  directory" data-zoomable="true"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you skip this step (which must be done each time you set up a new project), you may end up cloning repositories inside of each other, which will cause issues when committing and pushing changes to GitHub.</p></div><p>Once VS Code has opened/changed to the <code>/workspace/</code> directory, open the integrated terminal, and run the following command to clone your project repository:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PROJECT_REPOSITORY_URL</span></span></code></pre></div><p>Where <code>PROJECT_REPOSITORY_URL</code> is the URL of <strong>your own</strong> project repository (e.g.: <code>https://github.com/USERNAME/project-1-USERNAME.git</code> if using HTTPS, or <code>git@github.com:USERNAME/project-1-USERNAME.git</code> if using SSH, where <code>USERNAME</code> is your GitHub username). You can find this URL by following the <a href="#find-your-repository-url">Find Your Repository URL</a> step above.</p><p>Once the repository is cloned, open the project-specific <code>*.code-workspace</code> file (e.g.: <code>project-1.code-workspace</code>) by clicking on it in the file explorer. You should see a popup notification, typically on the bottom right of the window, that says <code>Open Workspace</code>:</p><p><img src="'+a+'" alt="Open Workspace popup" data-zoomable="true"></p><p>Click on <code>Open Workspace</code> to open the project-specific workspace (This will change VS Code&#39;s working directory to the project directory and load the project-specific settings). Once the workspace is open, you may get yet another notification asking if you would like to install the recommended extensions for the workspace:</p><p><img src="'+c+'" alt="Install recommended extensions popup" data-zoomable="true"></p><p>Click on <code>Install</code> to install the recommended extensions. Alternatively, you can install the recommended workspace extensions by pressing <code>CTRL+SHIFT+P</code> (or <code>CMD+SHIFT+P</code> on Mac) to open the command palette:</p><p><img src="'+d+'" alt="Command palette" data-zoomable="true"></p><p>Then, type <code>Extensions: Show Recommended Extensions</code>, and press <code>Enter</code>. Then, click on the cloud icon with a down arrow to install all recommended extensions:</p><p><img src="'+p+`" alt="Extensions sidebar with recommended extensions" data-zoomable="true"></p><p>Once the extensions are installed, you can now start working on your project! Note that the <code>*.code-workspace</code> file (e.g.: <code>project-1.code-workspace</code>) we provide is pre-configured with everything you need for one-click building/debugging. You can find more information on how to use the workspace file in the each project&#39;s <code>README.md</code> file.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>As you work on the project, remember to periodically commit and push your changes (e.g.: <code>git add</code>, <code>git commit</code>, and <code>git push</code>). Committing and pushing often protects your work in case something happens to your dev container, and gives you a history of checkpoints you can go back to if you need to.</p></div><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="accidentally-created-a-public-repository" tabindex="-1">Accidentally Created a Public Repository <a class="header-anchor" href="#accidentally-created-a-public-repository" aria-label="Permalink to &quot;Accidentally Created a Public Repository&quot;">​</a></h3><ul><li>Symptom: you selected <code>Public</code> instead of <code>Private</code> when creating your repository (or forgot to check the visibility setting).</li><li>Solution: immediately go to your repository&#39;s <code>Settings</code> tab, scroll to the bottom <code>Danger Zone</code> section, and click <code>Change visibility</code> to switch it to <code>Private</code>.</li></ul><h3 id="created-the-repository-under-the-wrong-owner" tabindex="-1">Created the Repository Under the Wrong Owner <a class="header-anchor" href="#created-the-repository-under-the-wrong-owner" aria-label="Permalink to &quot;Created the Repository Under the Wrong Owner&quot;">​</a></h3><ul><li>Symptom: you selected the <code>CSCI-442-Mines</code> organization (or some other account) as the <code>Owner</code> instead of your personal account, and the creation failed or the repository ended up somewhere unexpected.</li><li>Solution: delete the incorrectly created repository (<code>Settings &gt; Danger Zone &gt; Delete this repository</code>) and repeat the <a href="#create-a-repository-from-the-template">Create a Repository From the Template</a> steps, making sure to select your personal account as the <code>Owner</code>.</li></ul><h3 id="cloned-or-forked-the-template-instead-of-using-it" tabindex="-1">Cloned or Forked the Template Instead of Using It <a class="header-anchor" href="#cloned-or-forked-the-template-instead-of-using-it" aria-label="Permalink to &quot;Cloned or Forked the Template Instead of Using It&quot;">​</a></h3><ul><li>Symptom: you ran <code>git clone</code> directly on the template repository&#39;s URL, or used GitHub&#39;s <code>Fork</code> button instead of <code>Use this template</code>, and now your repository is linked to (or a fork of) the shared template repository instead of being an independent copy.</li><li>Solution: delete the repository you created and repeat the <a href="#create-a-repository-from-the-template">Create a Repository From the Template</a> steps, making sure to click the green <code>Use this template</code> button (<strong>not</strong> <code>Fork</code> or the template repository&#39;s own <code>Code</code> button).</li></ul><h3 id="cloning-using-https-instead-of-ssh" tabindex="-1">Cloning Using HTTPS Instead of SSH <a class="header-anchor" href="#cloning-using-https-instead-of-ssh" aria-label="Permalink to &quot;Cloning Using HTTPS Instead of SSH&quot;">​</a></h3><ul><li>Symptom: you receive an error message when cloning a repository similar to:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fatal: could not read Username for &#39;https://github.com&#39;: terminal prompts disabled</span></span>
<span class="line"><span>remote: Repository not found.</span></span></code></pre></div><ul><li>Solution: clone using the SSH URL (e.g.: <code>git@github.com:USERNAME/project-1-USERNAME.git</code>) instead of the HTTPS URL (e.g.: <code>https://github.com/USERNAME/project-1-USERNAME.git</code>).</li></ul><h3 id="cloning-using-ssh-instead-of-https-ssh-key-not-set-up-correctly" tabindex="-1">Cloning Using SSH Instead of HTTPS/SSH Key Not Set Up Correctly <a class="header-anchor" href="#cloning-using-ssh-instead-of-https-ssh-key-not-set-up-correctly" aria-label="Permalink to &quot;Cloning Using SSH Instead of HTTPS/SSH Key Not Set Up Correctly&quot;">​</a></h3><ul><li>Symptom: you receive an error message when cloning a repository similar to:</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git@github.com: Permission denied (publickey).</span></span>
<span class="line"><span>fatal: Could not read from remote repository.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please make sure you have the correct access rights</span></span>
<span class="line"><span>and the repository exists.</span></span></code></pre></div><ul><li>Solution: if you are intending on using HTTPS, use the HTTPS URL (e.g.: <code>https://github.com/USERNAME/project-1-USERNAME.git</code>). If you are intending on using SSH, make sure you set up your SSH key correctly by following the instructions in the <a href="/dev-container-setup#setup-git-inside-the-dev-container">Setup Git Inside the Dev Container</a> section.</li></ul><h3 id="can-t-find-the-project-specific-code-workspace-file-e-g-project-1-code-workspace" tabindex="-1">Can&#39;t Find The Project-Specific <code>*.code-workspace</code> File (e.g.: <code>project-1.code-workspace</code>) <a class="header-anchor" href="#can-t-find-the-project-specific-code-workspace-file-e-g-project-1-code-workspace" aria-label="Permalink to &quot;Can&#39;t Find The Project-Specific \`*.code-workspace\` File (e.g.: \`project-1.code-workspace\`)&quot;">​</a></h3><ul><li>Symptom: you can&#39;t find the project-specific <code>*.code-workspace</code> file (e.g.: <code>project-1.code-workspace</code>) in VS Code&#39;s file explorer.</li><li>Solution: make sure you have opened the top level of the workspace directory in the dev container (See the <a href="#clone-your-repository">Clone Your Repository</a> section above for more details).</li></ul><h3 id="missing-debug-configurations-tools" tabindex="-1">Missing Debug Configurations/Tools <a class="header-anchor" href="#missing-debug-configurations-tools" aria-label="Permalink to &quot;Missing Debug Configurations/Tools&quot;">​</a></h3><ul><li>Symptom: the VS Code debug configurations and/or build/debug tools (e.g.: <code>clang</code>, <code>cmake</code>, <code>gcc</code>, <code>g++</code>, <code>make</code>, etc.) are missing.</li><li>Solution: double check you have opened the course dev container <strong>first</strong>, and then opened the project-specific <code>*.code-workspace</code> file (e.g.: <code>project-1.code-workspace</code>) <strong>second</strong>. If you open the project-specific <code>*.code-workspace</code> file (e.g.: <code>project-1.code-workspace</code>) without first opening the course dev container (or in different dev container), the debug configurations and/or tools will be missing.</li></ul><p><em>This page created with the help of Claude AI.</em></p>`,51)]))}const w=o(l,[["render",h]]);export{k as __pageData,w as default};
